import sys, hashlib, hmac

P = 2**256 - 2**32 - 977
N_CURVE = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
Gx = 0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798
Gy = 0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8

def inv(a, m):
    return pow(a, -1, m)

def point_add(p, q):
    if p is None: return q
    if q is None: return p
    x1,y1 = p; x2,y2 = q
    if x1 == x2:
        if (y1 + y2) % P == 0:
            return None
        m = (3*x1*x1) * inv(2*y1, P) % P
    else:
        m = (y2 - y1) * inv((x2 - x1) % P, P) % P
    x3 = (m*m - x1 - x2) % P
    y3 = (m*(x1 - x3) - y1) % P
    return (x3, y3)

def scalar_mul(k, p):
    result = None
    addend = p
    while k:
        if k & 1:
            result = point_add(result, addend)
        addend = point_add(addend, addend)
        k >>= 1
    return result

def decompress(pub):
    prefix = pub[0]
    x = int.from_bytes(pub[1:33], 'big')
    y_sq = (pow(x,3,P) + 7) % P
    y = pow(y_sq, (P+1)//4, P)
    if (y & 1) != (prefix & 1):
        y = P - y
    return (x, y)

def compress(point):
    x, y = point
    prefix = b'\x02' if (y & 1) == 0 else b'\x03'
    return prefix + x.to_bytes(32, 'big')

def ckd_pub(K_par, c_par, i):
    # non-hardened
    data = compress_point_bytes(K_par) + i.to_bytes(4, 'big')
    I = hmac.new(c_par, data, hashlib.sha512).digest()
    IL = int.from_bytes(I[:32], 'big')
    IR = I[32:]
    if IL >= N_CURVE:
        raise ValueError('invalid')
    point = point_add(scalar_mul(IL, (Gx, Gy)), K_par)
    if point is None:
        raise ValueError('invalid')
    return point, IR

def compress_point_bytes(point):
    return compress(point)

B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'

def b58encode(b):
    n = int.from_bytes(b, 'big')
    s = ''
    while n > 0:
        n, r = divmod(n, 58)
        s = B58[r] + s
    for byte in b:
        if byte == 0:
            s = '1' + s
        else:
            break
    return s

def hash160(b):
    return hashlib.new('ripemd160', hashlib.sha256(b).digest()).digest()

def p2pkh(pub_compressed):
    h = hash160(pub_compressed)
    payload = b'\x00' + h
    checksum = hashlib.sha256(hashlib.sha256(payload).digest()).digest()[:4]
    return b58encode(payload + checksum)

def main():
    data = sys.stdin.read().split()
    pub_hex = data[0]
    chain_hex = data[1]
    n = int(data[2])
    pub_bytes = bytes.fromhex(pub_hex)
    chain = bytes.fromhex(chain_hex)
    K = decompress(pub_bytes)
    out = []
    for i in range(n):
        Ki, _ = ckd_pub(K, chain, i)
        addr = p2pkh(compress(Ki))
        out.append(f'{i}: {addr}')
    print('\n'.join(out))

main()
